<script setup lang="ts">
import {ref,shallowRef,computed,onMounted,onUnmounted} from 'vue';
import {newSled,tickSled,pauseSled,resumeSled,SLED_SECONDS} from './quick-engine';
const sled=shallowRef(newSled('demo'));const best=ref(0);const reduced=ref(false);const world=ref<HTMLButtonElement>();
let steer=0,target:number|null=null,dragging=false,last=0,raf=0;const held=new Set<string>();
const points=computed(()=>sled.value.crates*100+Math.floor(sled.value.elapsed)*5);
function start(){steer=0;target=null;held.clear();sled.value=newSled();}
function pause(){sled.value=sled.value.mode==='paused'?resumeSled(sled.value):pauseSled(sled.value);steer=0;target=null;held.clear();}
function nudge(direction:number){if(['demo','over','won'].includes(sled.value.mode))start();target=null;steer=direction;}
function clickNudge(event:MouseEvent,direction:number){if(event.detail!==0)return;if(['demo','over','won'].includes(sled.value.mode))start();if(sled.value.mode!=='playing')return;target=Math.max(95,Math.min(865,sled.value.x+direction*145));}
function stop(){steer=0;dragging=false;target=null;}
function point(event:PointerEvent){if(!world.value)return;const rect=world.value.getBoundingClientRect();target=(event.clientX-rect.left)/rect.width*960;}
function down(event:PointerEvent){if(event.button!==0)return;if(['demo','over','won'].includes(sled.value.mode))start();dragging=true;world.value?.setPointerCapture(event.pointerId);point(event);}
function move(event:PointerEvent){if(sled.value.mode==='playing'&&(dragging||event.pointerType==='mouse'))point(event);}
function keydown(event:KeyboardEvent){if(event.ctrlKey||event.metaKey||event.altKey||event.target instanceof HTMLAnchorElement)return;
 if(['ArrowLeft','KeyA','ArrowRight','KeyD'].includes(event.code)){event.preventDefault();if(['demo','over','won'].includes(sled.value.mode))start();held.add(event.code);target=null;steer=(held.has('ArrowRight')||held.has('KeyD')?1:0)-(held.has('ArrowLeft')||held.has('KeyA')?1:0);}
 if(event.code==='Space'){if(event.target instanceof HTMLElement&&event.target.closest('button,input,select,textarea'))return;event.preventDefault();if(event.repeat)return;if(['demo','over','won'].includes(sled.value.mode))start();else pause();}
 if(event.code==='Escape'||event.code==='KeyP'){event.preventDefault();if(!event.repeat)pause();}}
function keyup(event:KeyboardEvent){held.delete(event.code);steer=(held.has('ArrowRight')||held.has('KeyD')?1:0)-(held.has('ArrowLeft')||held.has('KeyA')?1:0);}
function blur(){sled.value=pauseSled(sled.value);stop();held.clear();}function visibility(){if(document.hidden)blur();}
onMounted(()=>{reduced.value=matchMedia('(prefers-reduced-motion: reduce)').matches;try{best.value=Number(localStorage.getItem('funapps-arctic-sled-best'))||0;}catch{}last=performance.now();
 const draw=(now:number)=>{const before=sled.value.mode;sled.value=tickSled(sled.value,(now-last)/1000,steer,target);last=now;if(before==='playing'&&['won','over'].includes(sled.value.mode)&&points.value>best.value){best.value=points.value;try{localStorage.setItem('funapps-arctic-sled-best',String(best.value));}catch{}}raf=requestAnimationFrame(draw);};raf=requestAnimationFrame(draw);
 window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);window.addEventListener('blur',blur);document.addEventListener('visibilitychange',visibility);});
onUnmounted(()=>{cancelAnimationFrame(raf);window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup);window.removeEventListener('blur',blur);document.removeEventListener('visibilitychange',visibility);});
</script>
<template>
<main class="sled-game">
 <header><a class="brand" href="https://funapps.ca/" aria-label="Back to FunApps">f<span>FunApps</span></a><h1>North of the Harbour<span>Supply Run</span></h1><a class="planner" href="?mode=planner">Expedition planner</a></header>
 <div class="icefield">
  <button ref="world" class="world" aria-label="Snowfield. Move left or right to catch orange supplies and avoid dark ice." @pointerdown="down" @pointermove="move" @pointerup="stop" @pointercancel="stop">
   <svg viewBox="0 0 960 590" preserveAspectRatio="none" role="img" aria-label="A sled moving through a snowy northern landscape. Orange supply crates slide toward you; dark ice patches are hazards.">
    <defs><linearGradient id="night" x2="0" y2="1"><stop stop-color="#07264b"/><stop offset="1" stop-color="#28708b"/></linearGradient><linearGradient id="snow" x2="0" y2="1"><stop stop-color="#b4e2ea"/><stop offset="1" stop-color="#f0fbf5"/></linearGradient></defs>
    <rect width="960" height="590" fill="url(#snow)"/><path d="M0 0H960V125L850 94 750 125 610 79 515 132 360 87 200 136 95 90 0 125Z" fill="url(#night)"/>
    <path d="M30 35q210 90 400-1t475 8" fill="none" stroke="#6be3c1" stroke-width="17" opacity=".3"/><path d="M20 29q200 90 400-1t485 8" fill="none" stroke="#99e8b5" stroke-width="3" opacity=".6"/>
    <circle cx="780" cy="34" r="15" fill="#e2f0d8"/><g fill="#fff" opacity=".75"><circle v-for="i in 18" :key="i" :cx="(i*137)%940" :cy="10+(i*37)%65" r="1.3"/></g>
    <path d="M0 590V115l86 36-25 30 56 50-65 39 38 44-35 52 22 54-46 42 47 70-26 58Z" fill="#447e99"/><path d="M960 590V115l-89 37 29 32-46 41 59 42-42 54 39 54-29 46 50 52-38 59 22 58Z" fill="#447e99"/>
    <path d="M5 141l68 22-31 33 51 39-65 37 38 46-36 50 22 54-37 43 39 65-24 60M955 143l-71 24 30 28-42 39 55 36-35 51 38 51-27 49 40 52-31 58 15 59" fill="none" stroke="#c7f1ef" stroke-width="7"/>
    <g :transform="`translate(0 ${reduced?0:(sled.elapsed*85)%120})`" opacity=".45"><path v-for="i in 7" :key="i" :d="`M130 ${i*120-120}q160-20 320 0t380-1`" fill="none" stroke="#8cc3d4" stroke-width="2"/></g>
    <g :transform="`translate(0 ${(sled.elapsed*164)%90})`" opacity=".3"><path v-for="i in 9" :key="i" :d="`M410 ${i*90-90}v15m140-15v15`" stroke="#6fa7bc" stroke-width="3" stroke-linecap="round"/></g>
    <g v-for="drop in sled.drops" :key="drop.id" :transform="`translate(${drop.x} ${drop.y})`" :opacity="drop.hit?0:1">
     <template v-if="drop.kind==='crate'"><ellipse cy="24" rx="33" ry="7" fill="#6a97a9" opacity=".25"/><rect x="-27" y="-26" width="54" height="48" rx="7" fill="#f19a42" stroke="#fff3c4" stroke-width="4"/><path d="M-25-7h50M-8-24v44M8-24v44" stroke="#b76130" stroke-width="4"/><rect x="-13" y="-14" width="26" height="26" rx="3" fill="#fff2c3"/><path d="M-7-1H7M0-8V6" stroke="#dc7631" stroke-width="5"/></template>
     <template v-else><path d="M-51 1l16-24 43-11 36 16 12 24-26 20-53-1Z" fill="#235c7d" stroke="#75b8cc" stroke-width="5"/><path d="m-32-5 20 10 10-16 18 14 21-9M-12 5l-8 14M16 3l7 16" fill="none" stroke="#d0f3f2" stroke-width="3"/></template>
    </g>
    <g :transform="`translate(${sled.x} 420)`" :opacity="sled.invincible>0&&Math.floor(sled.elapsed*12)%2===0?.4:1">
     <ellipse cy="24" rx="40" ry="12" fill="#34637a" opacity=".24"/><path d="M-30-39v76q0 13 12 13M30-39v76q0 13-12 13" fill="none" stroke="#315d79" stroke-width="7" stroke-linecap="round"/><rect x="-24" y="-32" width="48" height="68" rx="10" fill="#e47746" stroke="#fff0d0" stroke-width="4"/><path d="M-22 19h44M-22 7h44" stroke="#ab4c38" stroke-width="4"/><path d="M-17-9l-15-13M17-9l15-13" stroke="#df954e" stroke-width="9" stroke-linecap="round"/><ellipse cy="-13" rx="20" ry="24" fill="#ffd17c"/><circle cy="-26" r="14" fill="#f4ab7a"/><path d="M-17-28q0-25 34 0" fill="#ca573e"/><path d="M-17-29h34" stroke="#ffe4be" stroke-width="6" stroke-linecap="round"/>
    </g>
    <g v-if="sled.mode==='demo'" :transform="`translate(${sled.x} 465)`" fill="none" stroke="#357788" stroke-width="3" opacity=".7"><path d="M-85 0h48m-48 0 10-8m-10 8 10 8M85 0H37m48 0-10-8m10 8-10 8"/></g>
   </svg>
  </button>
  <div class="hud"><div><span>TO BASE</span><strong>{{ sled.mode==='demo'?45:Math.max(0,Math.ceil(SLED_SECONDS-sled.elapsed)) }}<small> sec</small></strong></div><div><span>SUPPLIES</span><strong>▣ {{ sled.crates }}</strong></div><div><span>SLED</span><strong :aria-label="`${sled.hearts} hearts`">{{ '♥'.repeat(sled.hearts) }}<b>{{ '♡'.repeat(3-sled.hearts) }}</b></strong></div><button class="pause" :disabled="!['playing','paused'].includes(sled.mode)" @click="pause">{{ sled.mode==='paused'?'Resume':'Pause' }}</button></div>
  <section v-if="sled.mode==='demo'" class="intro"><p>A MARITIMER. A SLED. A BIG NORTHERN SKY.</p><h2>Bring the<br/>good stuff home.</h2><div class="legend"><span>▣ Catch orange supplies</span><span>◆ Dodge dark ice</span></div><button class="start" @click="start">Let’s go</button><small>Move your mouse, drag, or use Left / Right</small></section>
  <section v-if="['paused','won','over'].includes(sled.mode)" class="result" aria-live="polite"><p>{{ sled.mode==='paused'?'A WARM LITTLE BREAK':sled.mode==='won'?'BACK AT HARBOUR BASE':'A BUMP IN THE SNOW' }}</p><h2>{{ sled.mode==='paused'?'Sled paused.':sled.mode==='won'?'Back at base!':'One more run?' }}</h2><template v-if="sled.mode!=='paused'"><strong>{{ points }}<small>points · {{ sled.crates }} supplies</small></strong><span>Personal best {{ best }}</span></template><button class="start" @click="sled.mode==='paused'?pause():start()">{{ sled.mode==='paused'?'Keep going':'Run again' }}</button></section>
  <div class="controls"><button class="steer" aria-label="Steer left" @pointerdown.prevent="nudge(-1)" @pointerup="stop" @pointercancel="stop" @pointerleave="stop" @click="clickNudge($event,-1)">◀ <span>Left</span></button><p>Catch ▣ <span>·</span> Dodge ◆<small>Move, drag, or hold Left / Right</small></p><button class="steer" aria-label="Steer right" @pointerdown.prevent="nudge(1)" @pointerup="stop" @pointercancel="stop" @pointerleave="stop" @click="clickNudge($event,1)"><span>Right</span> ▶</button></div>
  <div class="progress" role="progressbar" aria-label="Progress to harbour base" :aria-valuenow="Math.round(sled.elapsed/SLED_SECONDS*100)" aria-valuemin="0" aria-valuemax="100"><i :style="{width:sled.elapsed/SLED_SECONDS*100+'%'}"></i></div>
 </div>
 <footer><span>Different horizon. Same good mittens.</span><span>Fictional course · <a href="?mode=planner">Open the slower expedition planner</a></span></footer>
</main>
</template>
<style>
body{margin:0;background:#092b43;color:#fff;font-family:system-ui,-apple-system,sans-serif}*{box-sizing:border-box}.sled-game{min-height:100dvh;max-width:1800px;margin:auto;display:flex;flex-direction:column}.sled-game header{height:76px;padding:0 28px;display:flex;align-items:center;justify-content:space-between;gap:15px;background:#092b43}.sled-game .brand{font:bold italic 35px Georgia;text-decoration:none;color:#f9ba83;display:flex;align-items:center;gap:10px}.sled-game .brand span{font:700 14px system-ui;color:#fff}.sled-game h1{font-size:23px;font-weight:750;margin:0;letter-spacing:-.03em}.sled-game h1 span{font-size:15px;font-weight:400;color:#a5d3df;margin-left:12px}.sled-game .planner{color:#c3e5ea;font-size:14px;text-underline-offset:4px}.sled-game .icefield{position:relative;overflow:hidden;flex:1;min-height:490px;height:calc(100dvh - 124px);background:#c7e8eb}.sled-game .world{position:absolute;inset:0;width:100%;height:100%;border:0;padding:0;background:none;touch-action:none;cursor:ew-resize}.sled-game .world svg{width:100%;height:100%;display:block}.sled-game .hud{position:absolute;top:18px;left:22px;right:22px;display:flex;gap:22px;pointer-events:none;align-items:start}.sled-game .hud>div{padding:10px 18px;min-width:100px;background:#0c344ded;border:1px solid #b6e7eb66;border-radius:12px;box-shadow:0 5px 15px #123b4a22}.sled-game .hud span{font-size:11px;letter-spacing:.11em;font-weight:750;display:block;color:#a6d4de}.sled-game .hud strong{font-size:28px;line-height:1.3;display:block;color:#ffdb9c;font-variant-numeric:tabular-nums}.sled-game .hud small{font-size:14px;color:#d2e6e7;font-weight:400}.sled-game .hud b{color:#8eaeb9;font-weight:400}.sled-game .pause{margin-left:auto;pointer-events:auto;background:#0c344ded;color:#fff;border:1px solid #afdae2;border-radius:24px;min-height:44px;padding:8px 20px;font-size:14px;cursor:pointer}.sled-game .pause:disabled{opacity:.35;pointer-events:none}.sled-game .intro,.sled-game .result{position:absolute;top:48%;left:50%;transform:translate(-50%,-50%);width:min(460px,84%);padding:25px 30px;border-radius:20px;background:#103852f2;border:1px solid #b1d7d77a;box-shadow:0 15px 60px #17435450;text-align:center}.sled-game .intro p,.sled-game .result p{font-size:11px;letter-spacing:.13em;color:#a9d7dd;font-weight:800;margin:0 0 12px}.sled-game h2{font-size:clamp(30px,4vw,46px);line-height:1.05;margin:0 0 19px;letter-spacing:-.04em;font-weight:780;color:#fff7e7}.sled-game .legend{font-size:14px;display:flex;gap:16px;justify-content:center;margin-bottom:21px;color:#ffe0a4}.sled-game .legend span:last-child{color:#c3e3eb}.sled-game .start{border:0;background:#ffbf7b;color:#18394b;font-size:19px;min-height:55px;padding:11px 33px;font-weight:800;border-radius:11px;box-shadow:0 5px 0 #b76c4f;cursor:pointer}.sled-game .intro>small{display:block;margin:17px 0 0;color:#d1e6e8;font-size:13px}.sled-game .result>strong{display:block;color:#ffd69c;font-size:42px;line-height:1.25;margin-bottom:8px}.sled-game .result strong small{display:block;font-size:16px;font-weight:400}.sled-game .result>span{display:block;color:#bad9e1;font-size:14px}.sled-game .result .start{margin-top:21px}.sled-game .controls{position:absolute;left:26px;right:26px;bottom:20px;display:flex;gap:12px;align-items:center;justify-content:space-between;pointer-events:none}.sled-game .steer{pointer-events:auto;background:#113e57ed;border:2px solid #b8dce3;color:#fff;min-width:135px;min-height:62px;border-radius:13px;font-weight:750;font-size:22px;touch-action:none;cursor:pointer;box-shadow:0 4px 0 #48768b}.sled-game .steer span{font-size:16px;margin:0 5px}.sled-game .controls p{background:#f1fbf0ed;color:#174454;padding:9px 18px;border-radius:11px;font-size:15px;font-weight:700;text-align:center;margin:0}.sled-game .controls p span{padding:0 10px}.sled-game .controls small{display:block;font-size:12px;color:#557682;font-weight:450;margin-top:3px}.sled-game .progress{position:absolute;bottom:0;left:0;right:0;height:6px;background:#315f75}.sled-game .progress i{display:block;background:#ffb978;height:100%}.sled-game footer{min-height:48px;padding:10px 28px;display:flex;gap:12px;justify-content:space-between;align-items:center;color:#9fc6d3;font-size:12px}.sled-game footer a{color:#c8e1e6;text-underline-offset:3px}.sled-game button:focus-visible,.sled-game a:focus-visible{outline:3px solid #fff;outline-offset:3px}.sled-game button,.sled-game a{-webkit-tap-highlight-color:transparent}@media(max-width:650px){.sled-game header{height:64px;padding:0 14px}.sled-game .brand span{display:none}.sled-game h1{font-size:17px}.sled-game h1 span{display:block;font-size:12px;margin:0}.sled-game .planner{font-size:14px;max-width:72px;text-align:right}.sled-game .icefield{height:calc(100dvh - 106px);min-height:490px}.sled-game .hud{top:14px;left:10px;right:10px;gap:6px}.sled-game .hud>div{padding:8px 10px;min-width:0}.sled-game .hud strong{font-size:22px}.sled-game .hud span{font-size:12px}.sled-game .pause{font-size:12px;min-height:40px;padding:7px 11px}.sled-game .intro,.sled-game .result{top:45%;padding:23px 18px;width:86%;max-width:390px}.sled-game .intro p,.sled-game .result p{font-size:10px}.sled-game .intro h2{font-size:36px}.sled-game .legend{font-size:12px;gap:12px}.sled-game .controls{left:10px;right:10px;bottom:16px;gap:8px;align-items:end}.sled-game .steer{min-width:80px;min-height:66px;font-size:18px}.sled-game .steer span{display:block;font-size:13px}.sled-game .controls p{font-size:12px;padding:9px 11px}.sled-game .controls p span{padding:0 3px}.sled-game .controls small{font-size:10px;max-width:115px}.sled-game footer{padding:8px 14px;min-height:42px;font-size:11px}.sled-game footer>span:first-child{display:none}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style>
